import React, { use } from "react";
import '../css/login.css';
import { Link, useNavigate } from "react-router-dom";

class Welcome extends React.Component {
    render() {
        return (
            <main className="container mt-4 pt-5">
                <img
                    src="../img/aaa.png"
                    alt="fixed logo"
                    className="fixed-top-left"
                />

                <div className="container-fluid mt-5">
                    <div className="align-items-center position-fixed top-50 start-50 translate-middle w-100">
                        <div className="">
                            <div className="login-box-login shadow text-center item-back boder p-4 rounded-5">
                                <img src="../img/aaa.png" />
                                <div className="mt-5">
                                    <p>
                                        <b>سرویسی امن و راحت برای خدمت رسانی به مشتریان</b>
                                    </p>
                                    <div className="mx-4 mt-4">
                                        <a className="btn btn-primary w-100 rounded-3">شروع</a>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </main>
        );
    }
}

export default Welcome;
